<script setup lang="ts">
import { useRiskEvents, type RiskEvent } from '~/composables/useRiskEvents'
definePageMeta({ layout:'main', middleware:['auth','plearnd-admin'] })
const { list, show, acknowledge, resolve, dismiss } = useRiskEvents(); const rows=ref<RiskEvent[]>([]); const loading=ref(true); const severity=ref(''); const status=ref('open'); const rule_name=ref(''); const selected=ref<RiskEvent|null>(null); const note=ref('');
const load=async()=>{loading.value=true; try { rows.value=(await list({severity:severity.value||undefined,status:status.value==='all'?undefined:status.value,rule_name:rule_name.value||undefined})).data } finally { loading.value=false }}; onMounted(load)
const open=async(r:RiskEvent)=>{selected.value=(await show(r.id)).data; note.value=''}; const act=async(kind:'ack'|'resolve'|'dismiss')=>{if(!selected.value)return; if(kind==='ack') await acknowledge(selected.value.id); if(kind==='resolve') await resolve(selected.value.id,note.value); if(kind==='dismiss') await dismiss(selected.value.id,note.value); selected.value=null; await load()}
</script>
<template><div class="mx-auto max-w-7xl space-y-6 px-0 py-6 sm:px-6"><div><h1 class="text-2xl font-bold">{{ $t('admin.risk.title') }}</h1><p class="text-slate-500">{{ $t('admin.risk.subtitle') }}</p></div><div class="flex flex-wrap gap-3"><select v-model="severity" class="rounded-lg border p-2" @change="load"><option value="">{{ $t('admin.risk.all_severity') }}</option><option>low</option><option>medium</option><option>high</option><option>critical</option></select><select v-model="status" class="rounded-lg border p-2" @change="load"><option value="open">{{ $t('admin.risk.open') }}</option><option value="all">{{ $t('admin.risk.all') }}</option><option>acknowledged</option><option>resolved</option><option>dismissed</option></select><input v-model="rule_name" class="rounded-lg border p-2" :placeholder="$t('admin.risk.rule_filter')" @keyup.enter="load"></div><div class="overflow-auto rounded-2xl bg-white shadow"><table class="w-full text-left text-sm"><thead class="bg-slate-50"><tr><th class="p-3">{{ $t('admin.risk.severity') }}</th><th>{{ $t('admin.risk.rule') }}</th><th>{{ $t('admin.risk.subject') }}</th><th>{{ $t('admin.risk.created') }}</th><th>{{ $t('admin.risk.status') }}</th></tr></thead><tbody><tr v-for="r in rows" :key="r.id" class="cursor-pointer border-t hover:bg-slate-50" @click="open(r)"><td class="p-3"><span class="rounded-full px-2 py-1 text-xs" :class="r.severity==='high'||r.severity==='critical'?'bg-red-100 text-red-700':'bg-amber-100 text-amber-700'">{{r.severity}}</span></td><td>{{r.rule_name}}</td><td>{{r.subject_summary}}</td><td>{{new Date(r.created_at).toLocaleString()}}</td><td>{{r.status}}</td></tr><tr v-if="!loading&&!rows.length"><td colspan="5" class="p-8 text-center">{{ $t('admin.risk.empty') }}</td></tr></tbody></table></div><aside v-if="selected" class="fixed inset-y-0 right-0 w-full max-w-lg overflow-auto bg-white p-4 sm:p-6 shadow-2xl"><button class="float-right" @click="selected=null">×</button><h2 class="text-xl font-bold">{{selected.rule_name}}</h2><p class="mt-2">{{selected.subject_summary}}</p><pre class="mt-4 rounded bg-slate-100 p-4 text-xs">{{JSON.stringify(selected.evidence,null,2)}}</pre><textarea v-model="note" class="mt-4 w-full rounded border p-2" :placeholder="$t('admin.risk.note')"/><div class="mt-4 flex gap-2"><button class="min-h-[44px] sm:min-h-0 rounded bg-amber-600 px-3 py-2 text-white" @click="act('ack')">{{ $t('admin.risk.acknowledge') }}</button><button class="min-h-[44px] sm:min-h-0 rounded bg-emerald-600 px-3 py-2 text-white disabled:opacity-50" :disabled="!note" @click="act('resolve')">{{ $t('admin.risk.resolve') }}</button><button class="min-h-[44px] sm:min-h-0 rounded bg-slate-600 px-3 py-2 text-white disabled:opacity-50" :disabled="!note" @click="act('dismiss')">{{ $t('admin.risk.dismiss') }}</button></div></aside></div></template>
